<template>
  <section class="analysis">
    <template v-if="view === 'tokens'">
      <div class="section-heading"><div><h3>逐次模型用量</h3><p>按调用顺序查看上下文与输出规模。点击柱形查看这次调用。</p></div><span class="legend"><i></i>输入 <i class="output"></i>输出</span></div>
      <div v-if="models.length" class="token-scroll"><div class="token-chart" :style="{ minWidth: Math.max(450, models.length * 112) + 'px' }">
        <button v-for="(span, i) in models" :key="span.span_id" class="token-column" :class="{ selected: selectedId === span.span_id }" @click="$emit('select', span.span_id)">
          <span class="total">{{ tokenText(tokenTotal(span)) }}<small>总量</small></span>
          <span class="stack-area"><span class="stack"><span v-if="span.output_tokens !== null" class="segment output" :style="{ height: height(span.output_tokens) }"></span><span v-if="span.input_tokens !== null" class="segment" :style="{ height: height(span.input_tokens) }"></span></span><span v-if="span.input_tokens === null && span.output_tokens === null" class="missing">{{ span.total_tokens === null ? '未采集' : '仅总量' }}</span><span v-else-if="span.input_tokens === 0 && span.output_tokens === 0" class="missing">0</span></span>
          <b>调用 {{ i + 1 }}</b><span class="role">{{ role(span) }}</span><span class="usage">输入 {{ tokenText(span.input_tokens) }}<br>输出 {{ tokenText(span.output_tokens) }}</span>
          <small v-if="span.input_tokens === null || span.output_tokens === null" class="warning">输入或输出缺失</small>
        </button>
      </div></div><p v-else class="empty">暂无已记录的模型调用</p>
      <p class="note">柱高仅表示已知输入＋输出。供应商总量另列，可能与两者之和不同；缺失用量不按零计算。</p>
      <details><summary>按角色汇总与模型调用状态</summary><p>累计模型耗时 {{ milliseconds(metrics.model.duration_ms) }}{{ metrics.model.duration_complete ? '' : '（仅已知部分）' }} · {{ outcome(metrics.model) }} · 成功率 {{ rate(metrics.model.success_rate) }}</p><div class="table-scroll"><table><thead><tr><th>角色</th><th>调用状态</th><th>成功率</th><th>累计耗时</th><th>输入 Token</th><th>输出 Token</th><th>总 Token / 采集情况</th></tr></thead><tbody><tr v-for="item in metrics.model_details" :key="item.name"><th>{{ item.name }}</th><td>{{ item.total }} 次 · {{ outcome(item) }}</td><td>{{ rate(item.success_rate) }}</td><td>{{ milliseconds(item.duration_ms) }}{{ item.duration_complete ? '' : '（部分缺失）' }}</td><td>{{ tokenText(item.tokens.input_tokens) }}</td><td>{{ tokenText(item.tokens.output_tokens) }}</td><td>{{ tokenText(item.tokens.total_tokens) }}<small>已记录 {{ item.tokens.covered_calls }} 次，共 {{ item.tokens.total_calls }} 次</small></td></tr></tbody></table></div></details>
    </template>
    <template v-else-if="view === 'tools'">
      <div class="section-heading"><div><h3>工具调用分析</h3><p>查看使用频率、异常与已知耗时。展开一类工具可定位每次调用。</p></div><select v-model="sort" aria-label="工具排序"><option value="total">按调用次数</option><option value="failed">按失败次数</option><option value="duration">按已知累计耗时</option></select></div>
      <p class="note">{{ outcome(metrics.tool) }} · 成功率 {{ rate(metrics.tool.success_rate) }}<br>成功率只计算已记录且结果明确的成功与失败。中断和状态未确定未计入分母。</p>
      <div class="table-scroll"><table><thead><tr><th>工具</th><th>次数</th><th>失败</th><th>中断未完成</th><th>成功率</th><th>已知累计</th><th>已知平均</th><th>计时情况</th></tr></thead><tbody>
        <template v-for="tool in tools" :key="tool.name"><tr><th><button class="tool-name" :aria-expanded="openTool === tool.name" @click="openTool = openTool === tool.name ? '' : tool.name">{{ openTool === tool.name ? '▾' : '▸' }} {{ stepName(tool.name) }}<small>{{ tool.name.replace(/^tool\./, '') }}</small></button></th><td>{{ tool.total }}</td><td :class="{ red: tool.failed }">{{ tool.failed }}</td><td>{{ tool.interrupted }}</td><td>{{ rate(tool.successRate) }}</td><td>{{ milliseconds(tool.duration) }}</td><td>{{ milliseconds(tool.average) }}</td><td>{{ tool.timed === tool.total ? '均已记录' : `已计时 ${tool.timed} 次，共 ${tool.total} 次` }}</td></tr>
          <tr v-if="openTool === tool.name"><td colspan="8"><div class="tool-calls"><button v-for="(call, index) in tool.calls" :key="call.span_id" :class="{ selected: selectedId === call.span_id }" @click="$emit('select', call.span_id)">调用 {{ index + 1 }} · {{ spanState(call, false) }} · {{ milliseconds(durationMs(call)) }}</button></div><p class="note">成功 {{ tool.succeeded }} · 失败 {{ tool.failed }} · 中断未完成 {{ tool.interrupted }} · 状态未确定 {{ tool.unknown }}</p></td></tr>
        </template><tr v-if="!tools.length"><td colspan="8" class="empty">暂无已记录的工具调用</td></tr>
      </tbody></table></div><p class="note">平均耗时仅除以有可靠起止时间的次数。累计耗时可含并行调用，不能当作任务总耗时或占比。</p>
    </template>
    <template v-else>
      <div class="section-heading"><div><h3>异常调用 <span class="red">{{ errors.length }}</span></h3><p>仅包含模型和工具自身的失败或中断。点击定位执行轨迹。</p></div></div>
      <div v-if="errors.length" class="error-list"><button v-for="span in errors" :key="span.span_id" :class="{ selected: selectedId === span.span_id }" @click="$emit('locate', span.span_id)"><span class="error-dot"></span><div><b>{{ stepName(span.name) }}</b><small>{{ role(span) }} · {{ span.name }}</small></div><span>{{ spanState(span, false) }}<small>{{ milliseconds(durationMs(span)) }}</small></span><span>→</span></button></div><div v-else class="empty">未发现已记录的异常调用<p>这不代表行程业务质量已通过评估。</p></div>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import type { SpanSummary, TaskMetrics, CallMetrics } from '@/types'
import { stepName } from '@/services/api'
import { ancestors, buildForest, durationMs, isCall, milliseconds, spanState, tokenText, tokenTotal, toolRows } from '@/services/observationView'
const props = defineProps<{ view: 'tokens' | 'tools' | 'errors'; spans: SpanSummary[]; metrics: TaskMetrics; selectedId: string }>()
defineEmits<{ select: [id: string]; locate: [id: string] }>()
const sort = ref<'total' | 'failed' | 'duration'>('total'), openTool = ref('')
const forest = computed(() => buildForest(props.spans))
const models = computed(() => forest.value.ordered.filter(s => s.operation_type === 'llm'))
const maximum = computed(() => Math.max(1, ...models.value.map(s => (s.input_tokens ?? 0) + (s.output_tokens ?? 0))))
const height = (value: number) => `${value / maximum.value * 160}px`
function role(span: SpanSummary) { const agent = ancestors(forest.value, span.span_id).reverse().map(id => forest.value.nodes.get(id)!.span).find(s => s.operation_type === 'agent'); return agent ? stepName(agent.name) : '未归属' }
const errors = computed(() => forest.value.ordered.filter(s => isCall(s) && ['failed', 'interrupted'].includes(s.status)))
const tools = computed(() => toolRows(forest.value.ordered).sort((a, b) => (b[sort.value] ?? -1) - (a[sort.value] ?? -1) || a.name.localeCompare(b.name)))
const rate = (value: number | null) => value === null ? '暂无数据' : `${(value * 100).toFixed(1)}%`
const outcome = (value: CallMetrics) => `成功 ${value.succeeded} · 失败 ${value.failed} · 中断未完成 ${value.interrupted} · 状态未确定 ${value.unknown}`
</script>
<style scoped>
.analysis{padding:22px;min-width:0}.section-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;margin-bottom:18px}.section-heading h3{font-size:16px;margin:0 0 7px}.section-heading p,.note{font-size:11px;color:#7c8999;line-height:1.7;margin:0}.section-heading select{max-width:140px;border:1px solid #dde4e9;border-radius:5px;padding:6px;font-size:11px;background:white}.legend{font-size:11px;color:#718197;white-space:nowrap}.legend i{display:inline-block;width:8px;height:8px;background:#9fd5c3;border-radius:2px;margin-right:4px}.legend .output{background:#278f70;margin-left:10px}.token-scroll{overflow-x:auto;border-bottom:1px solid #edf0f3;margin-bottom:12px}.token-chart{display:flex;justify-content:space-around;gap:12px;padding:20px 10px 15px}.token-column{border:1px solid transparent;border-radius:7px;background:transparent;padding:10px 7px;min-width:95px;max-width:130px;flex:1;text-align:center;cursor:pointer;color:#536279}.token-column:hover{background:#f6faf8}.token-column.selected{background:#eff8f3;border-color:#9dcdb9}.total{display:block;color:#243e35;font-size:15px;font-weight:600;min-height:36px}.total small{display:block;color:#8b96a4;font-size:9px;font-weight:400}.stack-area{height:180px;display:flex;align-items:flex-end;justify-content:center;position:relative;border-bottom:1px solid #d9e4df;margin-bottom:12px}.stack{width:36px;display:flex;flex-direction:column;justify-content:flex-end;border-radius:4px 4px 0 0;overflow:hidden}.segment{display:block;background:#a3d6c5}.segment.output{background:#278f70}.missing{position:absolute;bottom:10px;font-size:11px;color:#8f9aab}.token-column b{font-size:11px}.role{font-size:10px;display:block;margin:6px 0;color:#7d8999}.usage{font-size:10px;line-height:1.8}.warning{display:block;font-size:9px;color:#a87545}.table-scroll{overflow-x:auto;margin:15px 0}.table-scroll table{border-collapse:collapse;width:100%;min-width:690px;text-align:left;font-size:11px}.table-scroll th,.table-scroll td{padding:12px 10px;border-bottom:1px solid #e9edf2;white-space:nowrap}.table-scroll thead{background:#f6f8fa;color:#7c8999;font-size:10px}.table-scroll td small,.tool-name small{display:block;font-weight:400;font-size:9px;color:#8b96a5;margin-top:4px}.tool-name{background:none;border:0;text-align:left;padding:0;cursor:pointer;color:#42546c}.tool-calls{display:flex;flex-wrap:wrap;gap:7px}.tool-calls button{padding:7px;border:1px solid #e0e6ec;border-radius:5px;background:white;font-size:10px;cursor:pointer}.tool-calls .selected{background:#eaf5f0;border-color:#9dcdb9}.red{color:#c76962}.error-list>button{width:100%;border:1px solid #e8edf1;border-radius:7px;display:flex;align-items:center;text-align:left;gap:12px;padding:14px;background:white;margin:10px 0;cursor:pointer;color:#506077}.error-list>button.selected{border-color:#9dcdb9;background:#eff8f3}.error-list div{flex:1;min-width:0;overflow-wrap:anywhere}.error-list b{font-size:12px}.error-list small{display:block;font-size:10px;color:#8995a4;margin-top:5px}.error-list>button>span{font-size:11px}.error-dot{width:7px;height:7px;background:#d47b75;border-radius:50%;flex-shrink:0}.empty{padding:50px 20px;text-align:center;color:#8895a5;font-size:12px}details{margin-top:25px;border-top:1px solid #e9edf2;padding-top:16px;font-size:11px;color:#728195}summary{cursor:pointer;margin-bottom:15px}button:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #21866b;outline-offset:2px}@media(max-width:600px){.analysis{padding:16px}.section-heading{flex-wrap:wrap}}
</style>
